निम्नलिखित C कोड स्निपेट का आउटपुट क्या होगा?

#include <stdio.h>
int main() {
    int a = 1;
    int b = a++ + ++a;
    printf("%d %d", a, b);
    return 0;
}

निम्नलिखित C++ प्रोग्राम का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
int main() {
    char s[] = "BPSC2024";
    char *p = s;
    cout << *(p + 4);
    return 0;
}

निम्नलिखित C++ प्रोग्राम का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
void fun(int x = 10, int y = 20) {
    cout << x + y;
}
int main() {
    fun(5);
    return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
int main() {
    int x = 10;
    try {
        if (x > 5) throw x;
    }
    catch (int e) {
        cout << "Caught: " << e;
    }
    return 0;
}
